class Solution:
    def rob(self, nums, colors):
        n = len(nums)
        dp = [0] * n
        pref = [0] * n
        for i in range(n):
            best = nums[i] + (pref[i-2] if i >= 2 else 0)
            if i >= 1 and colors[i] != colors[i-1]:
                best = max(best, nums[i] + pref[i-1])
            dp[i] = best
            pref[i] = max(dp[i], pref[i-1] if i else 0)
        return pref[n-1]

