class Solution {
    public int rob(int[] nums, int[] colors) {
        int n = nums.length;
        long[] dp = new long[n], pref = new long[n];
        for (int i = 0; i < n; i++) {
            long best = nums[i] + (i >= 2 ? pref[i-2] : 0);
            if (i >= 1 && colors[i] != colors[i-1])
                best = Math.max(best, nums[i] + pref[i-1]);
            dp[i] = best;
            pref[i] = Math.max(dp[i], i > 0 ? pref[i-1] : 0);
        }
        return (int)pref[n-1];
    }
}

